// The notes writer runs this adapter without installing npm packages.
import test from "node:test";
import assert from "node:assert/strict";
import { FOOTER_PATTERN } from "../release/notes-contract.ts";
import { newNotesAdapterFixture } from "../release/testing/notes-adapter.ts";
import * as notes from "./release-notes.ts";
import { spawnSync } from "node:child_process";
import {
  copyFileSync,
  mkdirSync,
  mkdtempSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const BASELINE = "## What's Changed\n* a change\n";
const HIGHLIGHTS =
  "A quiet release.\n\n### 🐛 Bug Fixes & Improvements\n\n- one fix\n";
const RUN = "https://github.com/muehz/agentics/actions/runs/42";
const FOOTER = `> Generated by [Agentics release](${RUN}) · copilot · gpt-5.6-luna?effort=high`;

test("only the agent's body reaches the bound release update", () => {
  const fixture = newNotesAdapterFixture();
  fixture.useState();
  const result = fixture.run({
    type: "update_release_notes",
    body: HIGHLIGHTS,
    repo: "different/repo",
    release_id: "99",
    sha: "f".repeat(40),
    staged: true,
    prerelease: false,
  });
  assert.equal(result.status, 0, result.output);
  const calls = fixture.calls();
  assert.equal(calls.length, 3);
  for (const call of calls)
    assert.ok(call.args.includes("repos/muehz/agentics/releases/42"));
  assert.ok(calls[1]!.args.includes("PATCH"));
  const patch = JSON.parse(calls[1]!.input);
  assert.deepEqual(Object.keys(patch), ["body"]);
  assert.ok(patch.body.includes(HIGHLIGHTS));
  assert.equal(fixture.readRelease().body, patch.body);
});

test("an invalid bound record fails before staged and unmatched no-ops", () => {
  for (const staged of ["true", "false"]) {
    const fixture = newNotesAdapterFixture();
    fixture.useState({ prerelease: "false" });
    fixture.env.GH_AW_SAFE_OUTPUTS_STAGED = staged;
    const result = fixture.run();
    assert.equal(result.status, 1, result.output);
    assert.match(
      result.output,
      /RELEASE_STATE_FILE\.prerelease must be a boolean/,
    );
    assert.deepEqual(fixture.calls(), []);
  }
});

test("the dependency-free CLI keeps the direct no-op order and fails closed on a missing artifact", (t) => {
  const root = mkdtempSync(join(tmpdir(), "agentics-release-notes-cold-"));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  // Copy the deployed module graph without installed packages.
  mkdirSync(join(root, "scripts"));
  mkdirSync(join(root, "release"));
  const script = join(root, "scripts", "release-notes.ts");
  copyFileSync(new URL("./release-notes.ts", import.meta.url), script);
  copyFileSync(
    new URL("./safe-output.ts", import.meta.url),
    join(root, "scripts", "safe-output.ts"),
  );
  copyFileSync(
    new URL("../release/notes-contract.ts", import.meta.url),
    join(root, "release", "notes-contract.ts"),
  );
  writeFileSync(join(root, "package.json"), JSON.stringify({ type: "module" }));
  const run = (env: NodeJS.ProcessEnv) =>
    spawnSync(process.execPath, [script], {
      cwd: root,
      encoding: "utf8",
      env,
    });
  const result = run({ GH_AW_SAFE_OUTPUTS_STAGED: "true" });
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout, "");
  assert.match(result.stderr, /safe outputs are staged; no API calls made/);
  const output = join(root, "agent-output.json");
  writeFileSync(output, JSON.stringify({ items: [] }));
  const unmatched = run({ GH_AW_AGENT_OUTPUT: output });
  assert.equal(unmatched.status, 0, unmatched.stderr);
  assert.match(unmatched.stderr, /no matching update_release_notes item/);
  for (const [path, diagnostic] of [
    ["", /RELEASE_STATE_FILE is required/],
    [join(root, "absent.json"), /could not read RELEASE_STATE_FILE/],
  ] as const) {
    const missing = run({
      GH_AW_SAFE_OUTPUTS_STAGED: "true",
      RELEASE_STATE_FILE: path,
      TARGET_SHA: "a".repeat(40),
    });
    assert.equal(missing.status, 1, missing.stderr);
    assert.match(missing.stderr, diagnostic);
  }
});

test("composes the enriched body", () => {
  const body = notes.composeBody(HIGHLIGHTS, BASELINE, FOOTER);
  assert.equal(
    body,
    `## 🌟 Release Highlights\n\n${HIGHLIGHTS}\n\n${FOOTER}\n\n<details>\n<summary>Full changelog</summary>\n\n${BASELINE}\n\n</details>\n`,
  );
});

test("a baseline left outside the changelog block is refused", () => {
  const body = `## 🌟 Release Highlights\n\n${HIGHLIGHTS}\n\n${FOOTER}\n\n${BASELINE}`;
  assert.equal(notes.classifyBody(body, HIGHLIGHTS, BASELINE), "unrecognized");
});

test("re-dispatch is a no-op", () => {
  const other = FOOTER.replace("/42", "/43");
  const body = notes.composeBody(HIGHLIGHTS, BASELINE, other);
  assert.equal(notes.classifyBody(body, HIGHLIGHTS, BASELINE), "enriched");
});

// The agent is an LLM: a retry over the same range almost never reproduces
// the previous run's exact wording. classifyBody must recognize the shape it
// already wrote even when this run's own `highlights` text disagrees with
// what is in the body, or every retry would fall through to the refusal
// branch instead of converging.
test("re-dispatch with different wording is still a no-op", () => {
  const reworded =
    "A different release summary entirely.\n\n### ✨ What's New\n\n- something else\n";
  const body = notes.composeBody(reworded, BASELINE, FOOTER);
  assert.equal(notes.classifyBody(body, HIGHLIGHTS, BASELINE), "enriched");
});

test("hand-edited notes are refused", () => {
  const body = `${notes.composeBody(HIGHLIGHTS, BASELINE, FOOTER)}\n\nsomeone's note\n`;
  assert.equal(notes.classifyBody(body, HIGHLIGHTS, BASELINE), "unrecognized");
});

test("the contract's footer pattern matches footerLine() and refuses a newline or an extra separator", () => {
  const saved = { ...process.env };
  Object.assign(process.env, {
    GITHUB_SERVER_URL: "https://github.com",
    GH_REPO: "muehz/agentics",
    GITHUB_RUN_ID: "42",
    NOTES_ENGINE: "copilot",
    NOTES_MODEL: "gpt-5.6-luna?effort=high",
  });
  try {
    const footer = notes.footerLine();
    assert.equal(footer, FOOTER);
    assert.match(footer, FOOTER_PATTERN);
    assert.doesNotMatch(`${footer}\nsecond line`, FOOTER_PATTERN);
    assert.doesNotMatch(`${footer} · extra`, FOOTER_PATTERN);
  } finally {
    process.env = saved;
  }
});

test("a missing engine fails", () => {
  const saved = { ...process.env };
  Object.assign(process.env, {
    GITHUB_SERVER_URL: "https://github.com",
    GH_REPO: "muehz/agentics",
    GITHUB_RUN_ID: "42",
    NOTES_MODEL: "gpt-5.6-luna?effort=high",
  });
  delete process.env.NOTES_ENGINE;
  try {
    assert.throws(() => notes.footerLine(), /NOTES_ENGINE is required/);
  } finally {
    process.env = saved;
  }
});

// The releases API returns null for a release with no body. Reading .length
// off it would end the job on a raw TypeError before the refusal branch below
// could fire, so the classifier has to absorb a non-string itself.
test("a null body is refused rather than crashing the job", () => {
  assert.equal(notes.classifyBody(null, HIGHLIGHTS, BASELINE), "unrecognized");
});

// FOOTER_PATTERN excludes · from both fields, so a footer carrying one is
// unmatchable by the very script that wrote it: every later dispatch would
// read its own output as notes it did not compose and refuse forever. The run
// that introduces one has to fail instead.
test("a · in the model fails its own run, not every later one", () => {
  const saved = { ...process.env };
  Object.assign(process.env, {
    GITHUB_SERVER_URL: "https://github.com",
    GH_REPO: "muehz/agentics",
    GITHUB_RUN_ID: "42",
    NOTES_ENGINE: "copilot",
    NOTES_MODEL: "gpt-5.6-luna · effort=high",
  });
  try {
    assert.throws(
      () => notes.footerLine(),
      /must not contain a newline or ·/,
      "footerLine accepted a separator it cannot later recognize",
    );
    assert.ok(
      !FOOTER_PATTERN.test(
        `> Generated by [Agentics release](${RUN}) · copilot · gpt-5.6-luna · effort=high`,
      ),
      "FOOTER_PATTERN now tolerates ·; footerLine's guard is stricter than it needs to be",
    );
  } finally {
    process.env = saved;
  }
});
